"""sample.log에서 ERROR 레벨 줄만 골라 마크다운 표로 출력한다."""
import re
import sys

LINE_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$")


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\n"))
            if m:
                rows.append({"time": m[1], "module": m[2], "message": m[3]})
    return rows


def escape(text):
    return text.replace("|", "\\|")


def main(argv):
    path = argv[1] if len(argv) > 1 else "sample.log"
    print("| time | module | message |")
    print("|---|---|---|")
    for r in parse_errors(path):
        print(f"| {escape(r['time'])} | {escape(r['module'])} | {escape(r['message'])} |")


if __name__ == "__main__":
    main(sys.argv)

